  void Theme(Control c){Color accent=launcherTheme==null?Color.FromArgb(185,150,76):launcherTheme.Accent;if(!(c is ProgressBar)){c.BackColor=c is TextBox||c is System.Windows.Forms.Button||c is ListBox||c is DataGridView?card:bg;c.ForeColor=fg;}var b=c as System.Windows.Forms.Button;if(b!=null){b.FlatAppearance.BorderColor=accent;b.UseVisualStyleBackColor=false;}var grid=c as DataGridView;if(grid!=null){grid.BackgroundColor=card;grid.DefaultCellStyle.BackColor=card;grid.DefaultCellStyle.ForeColor=fg;grid.DefaultCellStyle.SelectionBackColor=accent;grid.DefaultCellStyle.SelectionForeColor=launcherTheme!=null&&launcherTheme.Light?Color.White:Color.Black;grid.ColumnHeadersDefaultCellStyle.BackColor=card;grid.ColumnHeadersDefaultCellStyle.ForeColor=fg;grid.RowsDefaultCellStyle.ForeColor=fg;grid.AlternatingRowsDefaultCellStyle.BackColor=bg;}foreach(Control child in c.Controls)Theme(child);}
  bool downloadChanged;Dictionary<ulong,string> DownloadSelected(ulong[] ids){return DownloadSelected(ids,null);}
  Dictionary<ulong,string> DownloadSelected(ulong[] ids,Action<ulong[]> beforeDownload){var engine=GetEngine();ReportDownload(-1,"正在核对官方版本与本地缓存 · 不占用 Steam 游戏身份");var plan=WorkshopUpdate.Check(engine,ids,downloadCancel.Token);downloadChanged=plan.Needed.Count>0;if(downloadChanged){engine.Guard();if(beforeDownload!=null)beforeDownload(plan.Needed.ToArray());ReportDownload(-1,"发现更新或缺失内容 · 下载期间 Steam 可能暂显示游戏运行，子进程结束后释放");var downloaded=WorkshopWorker.Fetch(engine.Game,plan.Needed.ToArray(),ReportDownload,downloadCancel.Token,true);foreach(var p in downloaded)plan.Paths[p.Key]=p.Value;}else ReportDownload(100,"所选模组均已是最新 · 未调用下载接口，未占用 Steam 游戏身份");string cacheFile=Path.Combine(data,"workshop-paths.json");var stored=File.Exists(cacheFile)?new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(File.ReadAllText(cacheFile)):new Dictionary<string,string>();foreach(var p in plan.Paths)stored[p.Key.ToString()]=p.Value;File.WriteAllText(cacheFile,new JavaScriptSerializer().Serialize(stored));InstallWorkflow.Apply(engine,plan.Paths);return plan.Paths;}
  string InstallSelected3D(){return InstallSelected3D(operationModels);}
  string InstallSelected3D(bool includeModels){string installed=InstallWorkflow.Enable(GetEngine(),includeModels,DownloadSelected);try{return installed+"\r\n"+new ShaderSelection(UserDir(),Path.Combine(data,"settings-backups")).DefaultOnce(DefaultShaderMarker,false);}catch(Exception e){return installed+"\r\n3D 安装已完成，但默认光影未设置："+e.Message+"。请到光影列表手动选择。";}}
  void ApplyWorkshopPaths(Engine engine){try{string file=Path.Combine(data,"workshop-paths.json");if(!File.Exists(file))return;var map=new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(File.ReadAllText(file));string p;if(map.TryGetValue("3619862853",out p)&&Directory.Exists(p))engine.BuddySource=p;if(map.TryGetValue("3809306528",out p)&&Directory.Exists(p))engine.ViewSource=p;if(map.TryGetValue("3810302175",out p)&&Directory.Exists(p))engine.ModelsSource=p;}catch{}}
  void FetchWorkshop(){if(busy)return;componentShoot=false;componentChinese=false;Run(UpdateComponents,"正在核对工坊版本 · 最新内容直接复用缓存");}
  void ReportDownload(int value,string text){if(IsDisposed||!IsHandleCreated)return;BeginInvoke(new Action(()=>{if(!IsDisposed){bool measured=value>=0;if(measured)progress.Value=Math.Max(0,Math.Min(100,value));stage.Text=(measured?value+"% · ":"")+text;UpdateTask(text,measured);}}));}
  DlssInstaller CreateDlss(){var d=new DlssInstaller(GetEngine().Game,data);d.Progress=ReportDownload;return d;}
  void UpdateDlssState(){if(dlssState==null)return;try{dlssState.Text=DlssInstaller.Installed(path.Text.Trim(),data)?"检测到旧版 DLSS 安装，可恢复原文件。":"没有旧版 DLSS 安装，无需恢复。";}catch{dlssState.Text="请选择有效游戏目录。";}}
